args.script:
// bsky-post step 1: createSession with the account's app password.
// creds come in via vars (creds_json) — runner reads them from a local file,
// never echoed. Tokens live in page context only (window.__bsky), not saved.
(async () => {
  const CREDS = {{creds_json}};
  try {
    const r = await fetch('https://bsky.social/xrpc/com.atproto.server.createSession', {
      method: 'POST',
      credentials: 'omit',
      headers: {'content-type': 'application/json'},
      body: JSON.stringify({identifier: CREDS.identifier, password: CREDS.password})
    });
    const t = await r.text();
    let j = null; try { j = JSON.parse(t); } catch (e) {}
    if (!r.ok || !j || !j.accessJwt) {
      // 401 = bad identifier/app-password; never retry with the same creds
      return JSON.stringify({ok: false, status: r.status, err_head: t.slice(0, 140)});
    }
    window.__bsky = {accessJwt: j.accessJwt, did: j.did, handle: j.handle};
    return JSON.stringify({ok: true, handle: j.handle, did: j.did});
  } catch (e) {
    return JSON.stringify({ok: false, err: e.name + ': ' + e.message});
  }
})()

// bsky-post step 2: createRecord app.bsky.feed.post.
// 300-grapheme limit enforced in-engine (fallback to code points if no
// Intl.Segmenter). Threading: reply needs BOTH root and parent {uri, cid}.
(async () => {
  const ARGS = {{args_json}};
  try {
    const auth = window.__bsky;
    if (!auth) return JSON.stringify({ok: false, err: 'not logged in - login step failed?'});
    let n;
    if (typeof Intl.Segmenter === 'function') {
      const seg = new Intl.Segmenter('en', {granularity: 'grapheme'});
      n = [...seg.segment(ARGS.text)].length;
    } else {
      n = [...ARGS.text].length;
    }
    if (n > 300) return JSON.stringify({ok: false, err: 'over 300 graphemes: ' + n});
    const record = {text: ARGS.text, createdAt: new Date().toISOString(), langs: ['en']};
    if (ARGS.reply_to) {
      record.reply = {
        root: {uri: ARGS.root_uri, cid: ARGS.root_cid},
        parent: {uri: ARGS.reply_to, cid: ARGS.reply_to_cid}
      };
    }
    const r = await fetch('https://bsky.social/xrpc/com.atproto.repo.createRecord', {
      method: 'POST',
      credentials: 'omit',
      headers: {'content-type': 'application/json', 'authorization': 'Bearer ' + auth.accessJwt},
      body: JSON.stringify({repo: auth.did, collection: 'app.bsky.feed.post', record: record})
    });
    const t = await r.text();
    let j = null; try { j = JSON.parse(t); } catch (e) {}
    if (!r.ok || !j || !j.uri) {
      return JSON.stringify({ok: false, status: r.status, err_head: t.slice(0, 160)});
    }
    return JSON.stringify({ok: true, uri: j.uri, cid: j.cid, graphemes: n});
  } catch (e) {
    return JSON.stringify({ok: false, err: e.name + ': ' + e.message});
  }
})()

// bsky-post step 3: verify the post landed — getAuthorFeed, match text head.
(async () => {
  const ARGS = {{args_json}};
  try {
    const auth = window.__bsky;
    if (!auth) return JSON.stringify({ok: false, err: 'not logged in'});
    const head = (ARGS.text || '').replace(/\s+/g, ' ').trim().slice(0, 48);
    const r = await fetch('https://bsky.social/xrpc/app.bsky.feed.getAuthorFeed?actor='
      + encodeURIComponent(auth.did) + '&limit=10',
      {headers: {'authorization': 'Bearer ' + auth.accessJwt}});
    const t = await r.text();
    let j = null; try { j = JSON.parse(t); } catch (e) {}
    if (!r.ok || !j || !Array.isArray(j.feed)) {
      return JSON.stringify({ok: false, status: r.status, err_head: t.slice(0, 120)});
    }
    for (const item of j.feed) {
      const p = item && item.post;
      if (!p) continue;
      const flat = (p.record && p.record.text || '').replace(/\s+/g, ' ').trim();
      if (flat.startsWith(head.slice(0, 32))) {
        return JSON.stringify({ok: true, uri: p.uri, cid: p.cid, indexed_at: p.indexedAt});
      }
    }
    return JSON.stringify({ok: false, err: 'post not found in author feed (top 10)'});
  } catch (e) {
    return JSON.stringify({ok: false, err: e.name + ': ' + e.message});
  }
})()
